async function ensureSession(){if(session?.refresh_token&&Number(session.expires_at||0)<Math.floor(Date.now()/1000)+60){session=await auth("token?grant_type=refresh_token",{refresh_token:session.refresh_token});sessionStorage.setItem("opravao_admin_session",JSON.stringify(session))}}
async function api(resource,body=null,method="GET"){await ensureSession();const r=await fetch(FN+(method==="GET"?"?resource="+encodeURIComponent(resource):""),{method,headers:{apikey:KEY,Authorization:"Bearer "+session.access_token,"Content-Type":"application/json"},...(body?{body:JSON.stringify(body)}:{})});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error==="admin_forbidden"?"Tento účet nemá oprávnění správce.":j.error==="resend_not_configured"?"Odesílání e-mailů není nakonfigurováno v Resendu.":j.error==="email_send_failed"?"Resend odmítl odeslání: "+(j.detail||"neznámá chyba"):j.error==="invalid_lead_email"?"Zákazník nemá platnou e-mailovou adresu.":j.error==="email_sent_history_not_saved"?"E-mail odeslán, ale historie se neuložila.":(j.detail?j.error+": "+j.detail:j.error)||"Chyba serveru");return j}
function authErrorMessage(data,status){
 const code=data.code||data.error_code||"";
 const raw=data.msg||data.message||data.error_description||"";
 if(code==="invalid_credentials"||/invalid login credentials/i.test(raw))return "Nesprávný e-mail nebo heslo. Zkontrolujte údaje a zkuste to znovu.";
 if(code==="email_not_confirmed")return "E-mail není potvrzený. Nejprve ho potvrďte odkazem v e-mailu.";
 if(status===429)return "Příliš mnoho pokusů. Počkejte chvíli a zkuste přihlášení znovu.";
 if(status>=500)return "Přihlašovací služba je dočasně nedostupná. Zkuste to za chvíli.";
 return "Požadavek se nepodařilo dokončit. Zkuste to znovu nebo obnovte heslo.";
}
async function auth(path,body){
 let r;
 try{r=await fetch(URL+"/auth/v1/"+path,{method:"POST",headers:{apikey:KEY,"Content-Type":"application/json"},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});}
 catch(e){throw Error(e.name==="TimeoutError"||e.name==="AbortError"?"Server neodpověděl včas. Zkuste to znovu.":"Nelze se spojit se serverem. Zkontrolujte internet a zkuste to znovu.");}
 const j=await r.json().catch(()=>({}));
 if(!r.ok)throw Error(authErrorMessage(j,r.status));
 return j;
}
