async function refresh(){const d=await getRes("dashboard");leads=d.leads||[];partners=d.partners||[];revenue=d.revenue||[];settings=Object.fromEntries((d.settings||[]).map(x=>[x.key,x.value]));$("#mLeads").textContent=leads.length;$("#mNew").textContent=leads.filter(x=>["new","review"].includes(x.status)).length;$("#mDue").textContent=money(revenue.filter(x=>["pending","invoiced","overdue"].includes(x.status)).reduce((a,x)=>a+Number(x.amount||0),0));$("#mPaid").textContent=money(revenue.filter(x=>x.status==="paid").reduce((a,x)=>a+Number(x.amount||0),0));$("#priceSummary").textContent=money(settings.lead_pricing?.standard||149)+" / přijatá poptávka";$("#recentRows").innerHTML=leads.filter(x=>!archivedLeadIds().includes(x.id)).slice(0,6).map(x=>'<tr'+(x.due_at&&x.due_at<new Date().toISOString().slice(0,10)&&["pending","invoiced","overdue"].includes(x.status)?' class="billing-late"':'')+'><td>'+esc(when(x.created_at))+'</td><td>'+esc(x.payload?.repairType||x.note||"Oprava")+'</td><td>'+esc(x.place)+'</td><td>'+esc(x.email||x.phone)+'</td><td><span class="status">'+esc(human(x.status))+'</span></td><td><button type="button" class="opravao-trash" data-archive-overview="'+esc(x.id)+'" title="Přesunout do koše" aria-label="Přesunout poptávku do koše" ><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2m3 0-1 14H6L5 6m5 4v7m4-7v7"/></svg></button></td></tr>').join("")||'<tr><td colspan="6" class="empty">Zatím bez poptávek.</td></tr>';$("#distLead").innerHTML='<option value="">Vyberte prověřenou poptávku</option>'+leads.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.payload?.repairType||x.note||"Oprava")+" · "+esc(x.place)+" · "+esc(when(x.created_at))+"</option>").join("");$("#distPartner").innerHTML='<option value="">Vyberte opraváře</option>'+partners.filter(x=>!x.archived_at&&x.active&&x.status==="approved").map(x=>'<option value="'+esc(x.id)+'">'+esc(x.company_name)+" · "+money(x.price_per_lead)+"</option>").join("");if(settings.lead_pricing)Object.entries(settings.lead_pricing).forEach(([k,v])=>{const el=$('#pricingForm [name="'+k+'"]');if(el)el.value=v});const partnerRate=$('#partnerForm [name="price_per_lead"]');if(partnerRate&&settings.lead_pricing?.standard)partnerRate.value=settings.lead_pricing.standard;if(settings.business_model)for(const k of ["subscription_enabled","commission_enabled","featured_listing_enabled"]){const e=$('#pricingForm [name="'+k+'"]');if(e)e.checked=!!settings.business_model[k]}renderLeads();renderOverviewRecent();renderPartners();await loadDistribution();await loadRevenue()}
const archivedLeadKey="opravao_archived_leads";function archivedLeadIds(){try{return JSON.parse(localStorage.getItem(archivedLeadKey)||"[]")}catch{return []}}function setArchivedLead(id,archived){const ids=new Set(archivedLeadIds());archived?ids.add(id):ids.delete(id);localStorage.setItem(archivedLeadKey,JSON.stringify([...ids]))}

let leadLocationMap=null,leadLocationMarkers=null;
function leadCoordinates(lead){const p=lead.payload?.location,lat=Number(p?.lat),lon=Number(p?.lon);return Number.isFinite(lat)&&Number.isFinite(lon)&&lat>=48.4&&lat<=51.2&&lon>=12&&lon<=19?{lat,lon}:null}
function leadLocationHtml(lead){const point=leadCoordinates(lead);if(!point)return '<br><small class="lead-location-warning">Ověřit polohu</small>';const url='https://www.openstreetmap.org/?mlat='+point.lat+'&mlon='+point.lon+'#map=16/'+point.lat+'/'+point.lon;return '<br><a class="lead-map-link" href="'+url+'" target="_blank" rel="noopener">Otevřít mapu</a>'}
function renderLeadLocationMap(rows){
 const box=$("#lead-location-map"),status=$("#leadMapStatus");if(!box||!status)return;
 const located=rows.filter(x=>leadCoordinates(x));
 status.textContent=located.length+" poptávek má GPS bod; "+(rows.length-located.length)+" čeká na ověření adresy.";
 if(!window.L){status.textContent+=" Mapu se nepodařilo načíst; adresu otevřete z řádku poptávky.";return}
 if(!leadLocationMap){leadLocationMap=L.map(box,{scrollWheelZoom:false}).setView([49.82,15.47],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(leadLocationMap);leadLocationMarkers=L.layerGroup().addTo(leadLocationMap)}
 leadLocationMarkers.clearLayers();
 located.forEach(x=>{const p=leadCoordinates(x),title=esc(x.payload?.repairType||"Oprava"),address=esc(x.place||"Adresa neuvedena"),date=esc(when(x.created_at));L.marker([p.lat,p.lon]).bindPopup("<strong>"+title+"</strong><br>"+address+"<br>"+date).addTo(leadLocationMarkers)});
 if(located.length){const bounds=leadLocationMarkers.getBounds();leadLocationMap.fitBounds(bounds.isValid()?bounds.pad(located.length===1?0.08:0.18):[[49.82,15.47],[49.82,15.47]],{maxZoom:located.length===1?14:12})}
 setTimeout(()=>leadLocationMap?.invalidateSize(),120);
}

async function renderLeads(){const q=($("#searchLead")?.value||"").toLowerCase(),st=$("#filterStatus")?.value||"",loc=$("#filterLocation")?.value||"";const shown=leads.filter(x=>{const hasGps=!!leadCoordinates(x);return !archivedLeadIds().includes(x.id)&&(!st||x.status===st)&&(!loc||(loc==="mapped"?hasGps:!hasGps))&&[x.place,x.email,x.phone,x.name,x.note,x.assigned_to,x.next_action,x.payload?.repairType].join(" ").toLowerCase().includes(q)});$("#leadFilterSummary").textContent="Zobrazeno "+shown.length+" z "+leads.length+" poptávek";$("#exportLeads").disabled=!shown.length;renderLeadLocationMap(shown);$("#leadRows").innerHTML=shown.map(x=>'<tr><td>'+esc(when(x.created_at))+'</td><td><b>'+esc(x.payload?.repairType||x.note||"Oprava")+'</b><br>'+esc(x.name)+'<br>'+(x.phone?esc(x.phone)+'<br>':'')+esc(x.email)+'</td><td>'+esc(x.place)+'<br>'+esc(x.region)+leadLocationHtml(x)+'</td><td><select data-status="'+esc(x.id)+'">'+["new","review","contacted","waiting_customer","preparing_quote","quote_sent","waiting_decision","ordered","partner_assigned","completed","closed"].map(s=>'<option value="'+s+'" '+(s===x.status?"selected":"")+'>'+esc(human(s))+"</option>").join("")+'</select></td><td><input data-owner="'+esc(x.id)+'" placeholder="Odpovědný" value="'+esc(x.assigned_to)+'"><br><input data-next="'+esc(x.id)+'" placeholder="Další krok" value="'+esc(x.next_action)+'"></td><td>'+(x.payload?.registrationType==="company"?'<button class="button" data-convert-registration="'+esc(x.id)+'">Uložit jako opraváře</button> ':'')+'<button class="button alt" data-save-lead="'+esc(x.id)+'">Uložit</button> <button class="button alt" data-reply-lead="'+esc(x.id)+'">Odpovědět</button> <button type="button" class="opravao-trash" data-archive-lead="'+esc(x.id)+'" title="Přesunout do koše" aria-label="Přesunout poptávku do koše" ><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2m3 0-1 14H6L5 6m5 4v7m4-7v7"/></svg></button><small style="display:block">'+(Array.isArray(x.communication)?x.communication.length:0)+' zpráv</small></td></tr>').join("")||'<tr><td colspan="6" class="empty">Žádné odpovídající poptávky.</td></tr>';document.querySelectorAll("[data-archive-lead]").forEach(b=>b.onclick=()=>{const id=b.dataset.archiveLead;if(!confirm("Přesunout poptávku do koše? Poptávka zůstane uložená."))return;setArchivedLead(id,true);renderLeads();renderOverviewRecent();msg("#leadNotice","Poptávka přesunuta do koše. Obnovit ji můžete tlačítkem Zobrazit koš.")});document.querySelectorAll("[data-convert-registration]").forEach(b=>b.onclick=async()=>{const id=b.dataset.convertRegistration;b.disabled=true;b.textContent="Ukládám…";try{const result=await api("",{action:"convert_registration",lead_id:id},"POST");await refresh();go("partners");msg("#partnerNotice","Registrace byla uložena jako opravář "+(result.data?.company_name||"")+" a čeká na ověření.")}catch(err){msg("#leadNotice","Převod registrace selhal: "+err.message,true)}finally{b.disabled=false;b.textContent="Uložit jako opraváře"}});
document.querySelectorAll("[data-save-lead]").forEach(b=>b.onclick=async()=>{const id=b.dataset.saveLead,statusField=$('[data-status="'+id+'"]'),wasNew=statusField.value==="new",status=wasNew?"review":statusField.value;b.disabled=true;b.textContent="Ukládám…";try{await api("",{action:"update_lead",id,status,assigned_to:$('[data-owner="'+id+'"]').value,next_action:$('[data-next="'+id+'"]').value},"PATCH");if(wasNew)statusField.value="review";msg("#leadNotice",wasNew?"Poptávka uložena a označena jako přečtená.":"Poptávka uložena.");await refresh()}catch(e){msg("#leadNotice",e.message,true)}finally{b.disabled=false;b.textContent="Uložit"}})}
